SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "十一月乙酉李嗣源催定河东帅，李崧坚持用石敬瑭，群臣终从其议。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p021·原文件第26行", "note": "原文：乙酉，上以胡寇浸逼北边，命趣议河东帅；石敬瑭欲之，而范延光、赵延寿欲用康义诚，议久不决。枢密直学士李崧以为非石太尉不可。延光曰：“仆亦累奏用之，上欲留之宿卫耳。”会上遣中使趣之，众乃从崧议。；核对说明：主在本次分歧与范自言此前累奏用石均保，不能省成范从未荐石或李崧独任免；帝欲留宿卫为范所言，非独核帝心思。", "status": "draft", "id": "1b825dd9-7396-5744-a14d-57a64e640364", "subject_id": "9aa98b76-9036-5a22-9a7b-305eb0f857e2", "source_id": "68e013c2-2b03-510d-a522-9f27308b4a76"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "932年十一月乙酉", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p021·原文件第26行", "note": "原文：乙酉，上以胡寇浸逼北边，命趣议河东帅；石敬瑭欲之，而范延光、赵延寿欲用康义诚，议久不决。枢密直学士李崧以为非石太尉不可。延光曰：“仆亦累奏用之，上欲留之宿卫耳。”会上遣中使趣之，众乃从崧议。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "0ae87002-d57a-518e-b41d-fceda7ad7e11", "subject_id": "9aa98b76-9036-5a22-9a7b-305eb0f857e2", "source_id": "68e013c2-2b03-510d-a522-9f27308b4a76"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李嗣源：因北边受逼催议并遣中使者。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p021·原文件第26行", "note": "原文：乙酉，上以胡寇浸逼北边，命趣议河东帅；石敬瑭欲之，而范延光、赵延寿欲用康义诚，议久不决。枢密直学士李崧以为非石太尉不可。延光曰：“仆亦累奏用之，上欲留之宿卫耳。”会上遣中使趣之，众乃从崧议。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "0b06eaa9-0150-5db6-8228-c74ea596cc7b", "subject_id": "5d1886ff-b3ec-56f6-a154-b5633c294037", "source_id": "68e013c2-2b03-510d-a522-9f27308b4a76"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李嗣源：因北边受逼催议并遣中使者。", "citation": "卷278·长兴三年（932）·zztj-v278-y0932-p021·原文件第26行", "note": "原文：乙酉，上以胡寇浸逼北边，命趣议河东帅；石敬瑭欲之，而范延光、赵延寿欲用康义诚，议久不决。枢密直学士李崧以为非石太尉不可。延光曰：“仆亦累奏用之，上欲留之宿卫耳。”会上遣中使趣之，众乃从崧议。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "eb72cd50-5397-5626-ad7c-fbcce2eeffa1", "subject_id": "cf5a8d03-d5a0-510a-9e5a-75e05c0e3c6d